import { Big } from "big.js";

// BEGIN EXTRA CODE
function haversineKm(lat1, lon1, lat2, lon2) {
    const R = 6371;
    const dLat = ((lat2 - lat1) * Math.PI) / 180;
    const dLon = ((lon2 - lon1) * Math.PI) / 180;
    const a =
        Math.sin(dLat / 2) * Math.sin(dLat / 2) +
        Math.cos((lat1 * Math.PI) / 180) *
            Math.cos((lat2 * Math.PI) / 180) *
            Math.sin(dLon / 2) *
            Math.sin(dLon / 2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
// END EXTRA CODE

/**
 * Parses Overpass API JSON response and finds the nearest node (kade/dock) to the given lat/lon.
 * @param {Big} refLon - Reference longitude
 * @param {Big} refLat - Reference latitude
 * @param {string} overpassJson - JSON response from Overpass API
 * @returns {Promise.<string>}
 */
export async function JSA_Overpass_FindNearestKade(refLon, refLat, overpassJson) {
	// BEGIN USER CODE
    if (!overpassJson || refLat === undefined || refLon === undefined) {
        return JSON.stringify({ lat: null, lon: null, naam: null, error: "Ontbrekende invoer" });
    }
    try {
        const data = JSON.parse(overpassJson);
        const nodes = (data.elements || []).filter(e => e.type === "node" && e.lat && e.lon);
        if (nodes.length === 0) {
            return JSON.stringify({ lat: null, lon: null, naam: null, error: "Geen kades gevonden in de buurt" });
        }
        const lat = parseFloat(refLat.toString());
        const lon = parseFloat(refLon.toString());
        let best = null;
        let bestDist = Infinity;
        for (const n of nodes) {
            const d = haversineKm(lat, lon, n.lat, n.lon);
            if (d < bestDist) {
                bestDist = d;
                best = n;
            }
        }
        const naam = (best.tags && (best.tags.name || best.tags.description)) || `Kade (${bestDist.toFixed(1)} km)`;
        return JSON.stringify({ lat: best.lat, lon: best.lon, naam: naam, afstandKm: bestDist });
    } catch (e) {
        return JSON.stringify({ lat: null, lon: null, naam: null, error: e.message });
    }
	// END USER CODE
}
